// Draw checkerboard pattern
function drawSquare(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, size, size);
}

function drawChessBoard() {
    const squareSize = 50;
    const offsetX = 20;
    const offsetY = 20;

    // Draw horizontal lines
    for (let y = offsetY; y < H - offsetY; y += squareSize) {
        for (let x = offsetX; x < W - offsetX; x += squareSize) {
            if ((x + y) % (squareSize * 2) === 0) {
                drawSquare(x, y, squareSize, '#FFFFFF'); // White squares
            } else {
                drawSquare(x, y, squareSize, '#000000'); // Black squares
            }
        }
    }
}

// Draw game pieces (marbles)
function drawPiece(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size / 2, 0, Math.PI * 2);
    ctx.fill();
}

