  const angle = (i / 8) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 10);
  const startY = centerY + Math.sin(angle) * (maxRadius - 10);
  const endX = centerX + Math.cos(angle) * (maxRadius + 10);
  const endY = centerY + Math.sin(angle) * (maxRadius + 10);

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

