// Draw spiral
let angle = 0;
const maxIterations = 100;
const radiusIncrement = 5;

for (let iteration = 0; iteration < maxIterations; iteration++) {
  const radius = iteration * radiusIncrement;
  const x = W/2 + Math.cos(angle) * radius;
  const y = H/2 + Math.sin(angle) * radius;

  // Alternate between two colors per iteration
  if (iteration % 2 === 0) {
    ctx.fillStyle = colors[iteration % 6];
  } else {
    ctx.fillStyle = colors[(iteration + 1) % 6];
  }

  // Blocky shapes via fillRect
  ctx.fillRect(x - 2, y - 2, 4, 4);

  // Increase angle for spiral effect
  angle += 0.3;
}

